import fs from 'node:fs';

function replaceOnce(path, from, to, label) {
  const text = fs.readFileSync(path, 'utf8');
  const count = text.split(from).length - 1;
  if (count !== 1) throw new Error(`${label}: expected exactly one match; found ${count}.`);
  fs.writeFileSync(path, text.replace(from, to));
}
function appendOnce(path, marker, block, label) {
  const text = fs.readFileSync(path, 'utf8');
  if (text.includes(marker)) return;
  fs.writeFileSync(path, `${text.trimEnd()}\n\n${block.trim()}\n`);
}

const oldHuman = `function validateHumanAnswer(request,value,project){const type=request.answerType;const fail=m=>{const e=new Error(m);e.code='INVALID_HUMAN_ANSWER';e.requestId=request.requestId;throw e;};if(request.blocking!==false&&(value===undefined||value===null||value===''))fail(\`Answer is required for \${request.requestId}.\`);if(value===undefined||value===null||value==='')return true;if(type==='TEXT'||type==='LONG_TEXT'){if(typeof value!=='string'||!value.trim())fail('A non-empty string is required.');}else if(type==='BOOLEAN'){if(typeof value!=='boolean')fail('A Boolean answer is required.');}else if(type==='NUMBER'){if(typeof value!=='number'||!Number.isFinite(value))fail('A finite numeric answer is required.');}else if(type==='CHOICE'){if(!request.allowedValues.includes(value))fail('The answer must be one allowed value.');}else if(type==='MULTI_CHOICE'){if(!Array.isArray(value)||value.some(v=>!request.allowedValues.includes(v)))fail('Every selected answer must be an allowed value.');}else if(type==='DATE'){if(typeof value!=='string'||!/^\\d{4}-\\d{2}-\\d{2}$/.test(value)||Number.isNaN(Date.parse(value+'T00:00:00Z')))fail('An ISO YYYY-MM-DD date is required.');}else if(type==='FILE_REFERENCE'){if(typeof value!=='string'||!workflow.records(project,'artifacts',{active:true}).some(a=>workflow.recordId(a,'artifacts')===value))fail('A current canonical artifact ID is required.');}else fail(\`Unsupported answer type \${type}.\`);return true;}`;
const newHuman = `function validateHumanAnswer(request,value,project){const type=request.answerType;const fail=m=>{const e=new Error(m);e.code='INVALID_HUMAN_ANSWER';e.requestId=request.requestId;throw e;};const missing=value===undefined||value===null||value===''||(type==='MULTI_CHOICE'&&Array.isArray(value)&&value.length===0);if(request.blocking!==false&&missing)fail(\`Answer is required for \${request.requestId}.\`);if(missing)return true;const allowed=safe(request.allowedValues);if(type==='TEXT'||type==='LONG_TEXT'){if(typeof value!=='string'||!value.trim())fail('A non-empty string is required.');}else if(type==='BOOLEAN'){if(typeof value!=='boolean')fail('A Boolean answer is required.');}else if(type==='NUMBER'){if(typeof value!=='number'||!Number.isFinite(value))fail('A finite numeric answer is required.');}else if(type==='CHOICE'){if(!allowed.includes(value))fail('The answer must be one allowed value.');}else if(type==='MULTI_CHOICE'){if(!Array.isArray(value)||value.some(v=>!allowed.includes(v))||new Set(value).size!==value.length)fail('Every selected answer must be a unique allowed value.');}else if(type==='DATE'){if(typeof value!=='string'||!/^\\d{4}-\\d{2}-\\d{2}$/.test(value))fail('An ISO YYYY-MM-DD date is required.');const parsed=new Date(\`\${value}T00:00:00Z\`);if(Number.isNaN(parsed.getTime())||parsed.toISOString().slice(0,10)!==value)fail('A real ISO YYYY-MM-DD calendar date is required.');}else if(type==='FILE_REFERENCE'){if(typeof value!=='string'||!workflow.records(project,'artifacts',{active:true}).some(a=>workflow.recordId(a,'artifacts')===value))fail('A current canonical artifact ID is required.');}else fail(\`Unsupported answer type \${type}.\`);return true;}`;
replaceOnce('response-ingestion.js', oldHuman, newHuman, 'strict human-answer semantics');
