replaceOnce('response-ingestion.js', `    if(!Array.isArray(request.allowedValues))issues.push(issue('INVALID_ARRAY',\`\${path}/allowedValues\`,'allowedValues must be an array.'));`, `    if(!Array.isArray(request.allowedValues))issues.push(issue('INVALID_ARRAY',\`\${path}/allowedValues\`,'allowedValues must be an array.'));else if(['CHOICE','MULTI_CHOICE'].includes(request.answerType)&&(request.allowedValues.length===0||request.allowedValues.some(value=>typeof value!=='string'||!value.trim())||new Set(request.allowedValues).size!==request.allowedValues.length))issues.push(issue('INVALID_ALLOWED_VALUES',\`\${path}/allowedValues\`,'CHOICE and MULTI_CHOICE require non-empty, unique string allowedValues.'));`, 'choice contract');
