replaceOnce('response-ingestion.js', `    if(Object.values(envelope.records||{}).some(list=>safe(list).length))issues.push(issue('MIXED_RESPONSE_TYPE','/records','A clarification response cannot also propose canonical records.'));\n  }`, `    if(Object.values(envelope.records||{}).some(list=>safe(list).length))issues.push(issue('MIXED_RESPONSE_TYPE','/records','A clarification response cannot also propose canonical records.'));\n    if(safe(envelope.unresolved).some(item=>item.blocking!==false))issues.push(issue('MIXED_RESPONSE_TYPE','/unresolved','HUMAN_INPUT_REQUIRED must use humanInputRequests, not a second blocking unresolved channel.'));\n  }`, 'clarification response exclusivity');

replaceOnce('app-core.js', `function normalize(p){try{return p?.stages?ensureState(p):importSeed(p);`, `function normalize(p){try{if(p?.stages)return ensureState(core.migrateState(p));return importSeed(p);`, 'deterministic migration entry');
